<article class="card full"><h2>Eventos recientes</h2><?php if(!$dockerEvents): ?><p class="muted">No hay eventos JSONL disponibles.</p><?php endif; ?><div class="table-wrap"><table><thead><tr><th>Hora</th><th>Tipo</th><th>Severidad</th><th>Contenedor</th><th>Mensaje</th></tr></thead><tbody><?php foreach(array_slice($dockerEvents,0,20) as $event): ?><tr><td><?= docker_h($event['time']??'') ?></td><td><?= docker_h($event['type']??'') ?></td><td><?= docker_h($event['severity']??'') ?></td><td><?= docker_h($event['container_name']??'') ?></td><td><?= docker_h($event['message']??'') ?></td></tr><?php endforeach; ?></tbody></table></div></article>
